
import type { ServiceCategory, Service } from '@/types/services';

function slugify(text: string): string {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-') // Replace spaces with -
    .replace(/[^\w-]+/g, '') // Remove all non-word chars
    .replace(/--+/g, '-'); // Replace multiple - with single -
}

const facialSurgeryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'op-hunde', name: 'Nose Surgery (Rhinoplasty)', categorySlug: 'facial-surgery', description: `Rhinoplasty, expertly performed at Meva Clinic, is a sophisticated surgical procedure designed to refine and reshape the nose, enhancing its proportion with other facial features for overall harmony. Our board-certified surgeons address a comprehensive range of concerns, including nose size, width, bridge profile, tip definition, nostril symmetry, and asymmetry. Beyond aesthetic enhancement, rhinoplasty can also correct structural nasal defects, such as a deviated septum, to improve breathing functionality. Utilizing advanced surgical techniques, we meticulously sculpt nasal bone and cartilage to achieve natural, aesthetically pleasing results tailored to your unique facial anatomy and aesthetic goals. We invite you to explore the transformative possibilities of rhinoplasty through a comprehensive consultation at Meva Clinic.`, image: '/images/woman-getting-ready-nose-job-surgery (1).jpg', imageHint: 'nose surgery detail' },
  { id: 'rim-hunde', name: 'Nose Tip Reshaping', categorySlug: 'facial-surgery', description: `Nose tip reshaping, or tip-plasty, is a specialized form of rhinoplasty performed at Meva Clinic, focusing with precision on refining the nasal tip. This procedure expertly corrects concerns such as a bulbous, drooping, upturned, or asymmetrical tip, thereby enhancing the nose's overall definition and balance with other facial features. Our surgical techniques may involve intricate cartilage sculpting, strategic suturing, or delicate grafting. Tip-plasty is ideal for patients primarily concerned with the appearance of their nasal tip rather than the entire nasal structure. Discover how targeted nose tip reshaping by our specialists can refine your profile at Meva Clinic.`, image: '/images/Nose Tip Reshaping.png', imageHint: 'nose tip surgery' },
  { id: 'rim-vesheve', name: 'Ear Reshaping (Otoplasty)', categorySlug: 'facial-surgery', description: `Otoplasty, or ear reshaping surgery, available at Meva Clinic, is skillfully performed to correct the size, shape, or position of the ears, addressing aesthetic and psychological concerns. It commonly resolves protruding ears (pinning them closer to the head), overly large ears (macrotia), or ears misshapen due to injury or congenital conditions. The procedure involves the precise sculpting of ear cartilage by our experienced surgeons to achieve a more natural and aesthetically harmonious appearance. Suitable for both adults and children (typically after age 5-6 when ears are nearly fully developed), otoplasty can significantly boost self-confidence. Learn about personalized otoplasty options at Meva Clinic.`, image: '/images/otoplasty.png', imageHint: 'otoplasty results' },
  { id: 'mbj-flokeve', name: 'Hair Transplant', categorySlug: 'facial-surgery', description: `Hair transplant surgery at Meva Clinic offers a highly effective and lasting solution for various forms of hair loss, meticulously restoring hair to areas that are thinning or bald. The procedure involves harvesting healthy hair follicles from a donor area (typically the resilient posterior or lateral scalp) and skillfully implanting them into the recipient sites using advanced micro-surgical techniques. Follicular Unit Transplantation (FUT) or Follicular Unit Extraction (FUE) are employed to achieve natural-looking density and an aesthetically designed hairline. The transplanted hair is permanent and grows like your natural hair. Achieve a fuller, more youthful head of hair by exploring advanced hair transplant techniques at Meva Clinic.`, image: '/images/hair-transplant.png', imageHint: 'hair transplant before after' },
  { id: 'mbj-mjekres', name: 'Beard Transplant', categorySlug: 'facial-surgery', description: `A beard transplant at Meva Clinic expertly enhances facial hair density, defines the beard shape, or fills in patchy or sparse areas on the cheeks, chin, and mustache region for a more masculine appearance. Similar to advanced scalp hair transplants, this procedure involves extracting individual hair follicles (usually from the back of the scalp where hair is genetically robust) and meticulously implanting them into the beard region, considering natural hair growth patterns and density. It is an ideal solution for men seeking a fuller, more robust beard due to genetics, scarring, or previous hair removal. Achieve your desired beard aesthetic with our specialist team at Meva Clinic.`, image: '/images/Beard Transplant.png', imageHint: 'Beard Transplant results' },
  { id: 'mbj-vetullave', name: 'Eyebrow Transplant', categorySlug: 'facial-surgery', description: `Eyebrow transplant surgery at Meva Clinic skillfully restores or enhances the fullness, shape, and definition of eyebrows that are thin, sparse, or affected by scarring or over-plucking. Individual hair follicles are carefully extracted from a donor site (often the scalp) and then artfully implanted one by one into the eyebrow region. Our specialists meticulously follow the natural growth pattern and desired arch to create a permanent and remarkably natural-looking solution for beautifully defined eyebrows. Learn how an eyebrow transplant can frame your face and enhance your features by consulting with our experts at Meva Clinic.`, image: '/images/Eyebrow Transplant.png', imageHint: 'eyebrow transplant detail' },
  { id: 'lift-vetullave', name: 'Eyebrow Lift (Browplasty)', categorySlug: 'facial-surgery', description: `An eyebrow lift, or browplasty, performed at Meva Clinic, is a rejuvenating surgical procedure targeting the forehead and brow area. It effectively elevates sagging eyebrows, smooths deep forehead wrinkles, and softens frown lines between the brows. This procedure can create a more alert, youthful, and refreshed facial appearance, and may also improve the field of vision if drooping brows are causing obstruction. Our surgeons employ various advanced techniques, including endoscopic and traditional lifts, tailored to individual patient anatomy and aesthetic goals. Explore brow lift options and their revitalizing benefits at Meva Clinic.`, image: '/images/Eyebrow Lift (Browplasty).png', imageHint: 'eyebrow lift surgery' },
  { id: 'blefaroplastika', name: 'Eyelid Surgery (Blepharoplasty)', categorySlug: 'facial-surgery', description: `Eyelid surgery, or blepharoplasty, is a precise surgical procedure offered at Meva Clinic to improve the appearance and function of the eyelids. It can be performed on the upper eyelids, lower eyelids, or both. Upper blepharoplasty removes excess skin and fat that can cause hooding, a tired look, or even impair vision. Lower blepharoplasty addresses puffiness, under-eye bags, and fine wrinkles. The result is a more rested, youthful, and alert eye appearance, restoring a natural and refreshed look. Discover how expert eyelid surgery can rejuvenate your eyes and address functional concerns at Meva Clinic.`, image: '/images/Eyelid Surgery (Blepharoplasty).png', imageHint: 'eyelid surgery results' },
  { id: 'lift-fytyres', name: 'Face Lift (Rhytidectomy)', categorySlug: 'facial-surgery', description: `A facelift, or rhytidectomy, at Meva Clinic is a comprehensive surgical procedure meticulously designed to address significant signs of aging in the mid to lower face and neck regions. This sophisticated surgery involves lifting and tightening underlying facial muscles (SMAS layer), repositioning displaced fat, and expertly removing excess skin. The aim is to smooth deep wrinkles, reduce jowls, correct sagging, and restore more youthful, defined facial contours. Tailored to individual anatomical needs and aesthetic desires, a facelift provides long-lasting, natural-looking rejuvenation. Learn about personalized facelift approaches and achieve a more youthful you by consulting with our board-certified surgeons at Meva Clinic.`, image: '/images/Face Lift (Rhytidectomy).png', imageHint: 'face lift surgery' },
  { id: 'rim-mjekres', name: 'Chin Augmentation (Genioplasty)', categorySlug: 'facial-surgery', description: `Chin augmentation, or genioplasty, is a surgical procedure at Meva Clinic that enhances the size and projection of a recessed or "weak" chin, significantly improving facial balance and profile harmony. This enhancement can be achieved through the precise surgical insertion of a custom-fit biocompatible chin implant or by an osteotomy procedure that repositions the chin bone (sliding genioplasty). A well-defined chin strengthens the jawline and contributes to a more aesthetically pleasing and balanced facial structure. Discuss your chin augmentation options and desired outcomes with our experienced plastic surgeons at Meva Clinic.`, image: '/images/Chin Augmentation (Genioplasty).png', imageHint: 'chin augmentation surgery' },
];

const facialTreatmentsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'lip-reshaping', name: 'Lip Reshaping & Augmentation', categorySlug: 'facial-treatments', description: `Lip reshaping and augmentation at Meva Clinic expertly enhances lip volume, defines the lip border (vermilion border), corrects asymmetry, and smooths fine perioral lines. This is most commonly achieved using injectable dermal fillers, predominantly hyaluronic acid-based, known for providing natural-looking and temporary results. The procedure is quick, with minimal downtime, offering an immediate and noticeable improvement in lip contour, fullness, and overall facial aesthetics. Explore customized lip enhancement techniques for your perfect pout with our skilled injectors at Meva Clinic.`, image: '/images/Lip Reshaping & Augmentation.png', imageHint: 'lip fillers application' },
  { id: 'xanthelasma-plasma-arc', name: 'Xanthelasma Removal (Plasma Arc)', categorySlug: 'facial-treatments', description: `Xanthelasma removal using advanced Plasma Arc technology at Meva Clinic is a precise, non-invasive treatment for yellowish cholesterol deposits (xanthelasmata) that appear on or around the eyelids. The Plasma Arc device generates a tiny, controlled electrical arc that sublimates (vaporizes) the targeted superficial tissue without causing significant thermal damage to the surrounding healthy skin. This method offers excellent cosmetic results with minimal scarring, reduced risk, and significantly less downtime compared to traditional surgical excision. Learn about this effective and gentle removal method for xanthelasma at Meva Clinic.`, image: '/images/Xanthelasma Removal (Plasma Arc).png', imageHint: 'xanthelasma plasma device' },
  { id: 'multivitamin-treatment', name: 'Multivitamin Infusion Facial', categorySlug: 'facial-treatments', description: `The Multivitamin Infusion Facial at Meva Clinic is a luxurious and highly effective aesthetic treatment that delivers a potent, customized cocktail of essential vitamins, powerful antioxidants, peptides, and hydrating agents directly into the skin via mesotherapy or similar techniques. This nourishing infusion combats signs of photoaging, brightens dull complexions, deeply hydrates dry or dehydrated skin, and improves overall skin health, tone, and resilience. Tailored to your skin’s specific needs, this facial promotes a radiant, revitalized glow and supports long-term skin vitality. Discover the rejuvenating benefits of targeted vitamin therapy for your skin at Meva Clinic.`, image: '/images/Multivitamin Infusion Facial.png', imageHint: 'vitamin facial therapy' },
  { id: 'eyelids-plasma-arc', name: 'Non-Surgical Eyelid Lift (Plasma Arc)', categorySlug: 'facial-treatments', description: `A Non-Surgical Eyelid Lift using Plasma Arc technology, often referred to as "fibroblast therapy" or "plasma pen treatment," available at Meva Clinic, offers a minimally invasive alternative to surgical blepharoplasty for addressing mild to moderate sagging of the upper or lower eyelids (dermatochalasis). The plasma device creates a series of precisely controlled micro-dots on the skin’s surface, which triggers immediate skin contraction and tightening, while also stimulating long-term collagen and elastin production. This results in a lifted, more youthful eye appearance with reduced hooding, wrinkles, and crepiness. Find out if this innovative eyelid lift is suitable for your specific concerns at Meva Clinic.`, image: '/images/Non-Surgical Eyelid Lift (Plasma Arc).png', imageHint: 'plasma eyelid treatment' },
  { id: 'cheekbone-reshaping', name: 'Cheekbone Contouring (Fillers)', categorySlug: 'facial-treatments', description: `Cheekbone contouring with dermal fillers at Meva Clinic is an artful procedure that enhances the definition, volume, and youthful contours of the cheekbones, or restores age-related volume loss in the mid-face. Strategically injected hyaluronic acid fillers can lift and support the malar region, improve facial balance, soften nasolabial folds, and create a more sculpted, V-shaped facial appearance. The procedure offers immediate, noticeable results with minimal downtime, tailored to your unique facial anatomy. Learn about personalized cheekbone enhancement possibilities with our expert aesthetic injectors at Meva Clinic.`, image: '/images/Cheekbone Contouring (Fillers).png', imageHint: 'cheek fillers injection' },
  { id: 'microdermabrasion', name: 'Microdermabrasion', categorySlug: 'facial-treatments', description: `Microdermabrasion at Meva Clinic is a non-invasive skin resurfacing treatment that gently exfoliates the stratum corneum (the outermost layer of dead skin cells) using a diamond-tipped wand or fine, inert crystals. This mechanical exfoliation process reveals smoother, brighter, and more even-toned skin beneath. It effectively reduces the appearance of fine lines, minor acne scars, sun damage, enlarged pores, and textural irregularities, while also stimulating collagen production for improved skin elasticity and health. Experience revitalized, glowing skin with our professional microdermabrasion treatments at Meva Clinic.`, image: '/images/Microdermabrasion.png', imageHint: 'microdermabrasion skin procedure' },
  { id: 'jawline-contouring', name: 'Jawline Contouring (Fillers/Threads)', categorySlug: 'facial-treatments', description: `Jawline contouring at Meva Clinic aims to create a sharper, more defined, and youthful mandibular border, enhancing overall facial harmony. This can be achieved non-surgically using strategically placed dermal fillers (e.g., hyaluronic acid or calcium hydroxylapatite) to add volume, structure, and projection, or with PDO threads to lift sagging skin in the jowl area and tighten the jawline. These treatments can improve the definition between the face and neck, balance the profile, and reduce the appearance of a "double chin" or an undefined, aging jawline. Explore advanced, personalized jawline enhancement options with our aesthetic experts at Meva Clinic.`, image: '/images/Jawline Contouring FillersThreads.png', imageHint: 'jawline fillers procedure' },
  { id: 'wrinkle-fillers', name: 'Dermal Fillers for Wrinkles', categorySlug: 'facial-treatments', description: `Dermal fillers offered at Meva Clinic are expertly administered injectable treatments designed to effectively smooth out fine lines, moderate-to-severe wrinkles, and deeper facial folds. Most commonly formulated with hyaluronic acid, a substance naturally found in the skin, these fillers work by restoring lost volume beneath the skin\'s surface, plumping up creases, and providing a more youthful, refreshed appearance. They are versatile and can be used to treat areas such as nasolabial folds (smile lines), marionette lines, perioral lines (around the mouth), and forehead lines. Discover various advanced filler options for effective and natural-looking wrinkle reduction at Meva Clinic.`, image: '/images/Dermal Fillers for Wrinkles.png', imageHint: 'dermal fillers face application' },
  { id: 'prp-face', name: 'PRP Facial Rejuvenation', categorySlug: 'facial-treatments', description: `PRP (Platelet-Rich Plasma) Facial Rejuvenation, popularly known as a "vampire facial," at Meva Clinic, harnesses the potent healing and regenerative properties of your own blood to stimulate comprehensive skin renewal. A small sample of your blood is processed to concentrate platelets, which are rich in growth factors. This concentrated PRP is then meticulously reintroduced into the facial skin, typically via microneedling or direct injection. This process promotes robust collagen and elastin production, improves skin texture and tone, reduces fine lines and wrinkles, minimizes pore size, and enhances overall skin radiance and health. Learn about the natural, autologous benefits of PRP facials for holistic skin revitalization at Meva Clinic.`, image: '/images/PRP Facial Rejuvenation.png', imageHint: 'prp facial therapy procedure' },
  { id: 'dark-circles-treatment', name: 'Under-Eye Dark Circles Treatment', categorySlug: 'facial-treatments', description: `Under-eye dark circles and hollows (tear trough deformity) can contribute to a tired, aged, or drawn appearance. At Meva Clinic, treatment options are tailored to the underlying cause and may include specialized dermal fillers (tear trough fillers) to restore lost volume and smooth the transition between the lower eyelid and cheek. Other approaches involve topical treatments with active ingredients like Vitamin K, retinol, or peptides; gentle chemical peels to improve skin tone and texture; or advanced laser therapy to address pigmentation and vascularity. A personalized approach is crucial for effectively refreshing and rejuvenating the delicate under-eye area. Find tailored solutions for your under-eye concerns at Meva Clinic.`, image: '/images/Under-Eye Dark Circles Treatment.png', imageHint: 'dark circles eye treatment' },
  { id: 'prp-hair', name: 'PRP Hair Restoration', categorySlug: 'facial-treatments', description: `PRP (Platelet-Rich Plasma) Hair Restoration at Meva Clinic is an advanced, non-surgical treatment for various types of hair loss and thinning in both men and women. The procedure involves drawing a small amount of your own blood, processing it to concentrate the platelets rich in growth factors, and then injecting this PRP solution into the scalp in areas of hair thinning. These growth factors stimulate dormant or underperforming hair follicles, promote new hair growth, increase hair shaft thickness, and improve overall scalp health. It is a natural and safe option that can be used as a standalone treatment or in conjunction with other hair restoration therapies. Explore the potential of PRP for natural hair regrowth at Meva Clinic.`, image: '/images/PRP Hair Restoration.png', imageHint: 'prp hair treatment scalp' },
  { id: 'white-peeling', name: 'Chemical Peels (White Peeling)', categorySlug: 'facial-treatments', description: `Chemical peels, including "White Peeling" or superficial peels available at Meva Clinic, utilize mild, professionally formulated acidic solutions (such as glycolic acid, lactic acid, or salicylic acid) to gently and controllably exfoliate the outermost layer of the epidermis. This process effectively removes accumulated dead skin cells, unclogs pores, improves skin tone and texture, reduces minor blemishes, lightens superficial pigmentation, and stimulates cellular turnover for a brighter, smoother, and more refined complexion. These peels are ideal for regular skin maintenance, addressing mild acne, and achieving a refreshed glow with minimal downtime. Discover the refreshing benefits of gentle chemical peels at Meva Clinic.`, image: '/images/Chemical Peels (White Peeling).png', imageHint: 'chemical peel skin application' },
  { id: 'microneedling', name: 'Microneedling (Collagen Induction Therapy)', categorySlug: 'facial-treatments', description: `Microneedling, also known as Collagen Induction Therapy (CIT), performed at Meva Clinic, is a minimally invasive procedure that uses a specialized device equipped with fine, sterile needles to create controlled micro-injuries in the skin. These precisely created micro-channels trigger the body\'s natural wound healing cascade, leading to a significant boost in collagen and elastin production. This results in improved skin texture, firmness, and elasticity; reduced appearance of scars (including acne scars and surgical scars), fine lines, wrinkles, and enlarged pores; and overall skin rejuvenation, leading to firmer, more youthful-looking skin. Learn about the transformative power of microneedling for skin health at Meva Clinic.`, image: '/images/Microneedling (Collagen Induction Therapy).png', imageHint: 'microneedling device skin' },
  { id: 'radiofrequency-face', name: 'Radiofrequency Skin Tightening (Face)', categorySlug: 'facial-treatments', description: `Radiofrequency (RF) Skin Tightening for the face, offered at Meva Clinic, is a non-invasive aesthetic treatment that utilizes RF energy to generate controlled heat in the deeper layers of the skin (dermis and subdermal tissue). This thermal effect causes existing collagen fibers to contract and tighten, while simultaneously stimulating the production of new collagen and elastin over subsequent weeks and months. The result is visibly firmer, tighter, and smoother skin, with a reduction in fine lines, wrinkles, and mild skin laxity. It\'s an excellent non-surgical option for addressing early signs of aging on the face and neck without downtime. Experience advanced facial skin tightening with our state-of-the-art RF technology at Meva Clinic.`, image: '/images/Radiofrequency Skin Tightening (Face).png', imageHint: 'radiofrequency facial treatment' },
  { id: 'sulcus-filling', name: 'Nasolabial Fold Fillers (Sulcus Filling)', categorySlug: 'facial-treatments', description: `Nasolabial folds, commonly referred to as smile lines or laugh lines, are the prominent creases that extend from the sides of the nose to the corners of the mouth, often deepening with age due to volume loss and skin laxity. At Meva Clinic, dermal fillers, typically hyaluronic acid-based, are skillfully and strategically injected directly into these folds or adjacent areas to replenish lost volume, lift the overlying skin, and significantly soften their appearance. This targeted treatment provides immediate, natural-looking results, restoring a smoother, more youthful contour to the mid-face and reducing the visual impact of aging. Effectively soften your smile lines with our expert injectors at Meva Clinic.`, image: '/images/Nasolabial Fold Fillers (Sulcus Filling).png', imageHint: 'smile line fillers injection' },
  { id: 'chin-reshaping', name: 'Non-Surgical Chin Reshaping (Fillers)', categorySlug: 'facial-treatments', description: `Non-surgical chin reshaping at Meva Clinic utilizes injectable dermal fillers to expertly enhance the projection, shape, volume, and definition of the chin without the need for invasive surgery. This procedure can effectively improve facial balance, strengthen a weak or recessed chin (microgenia), create a more harmonious profile, and even elongate the face subtly. Hyaluronic acid fillers are carefully placed by our experienced injectors to achieve subtle yet impactful, natural-looking results, with minimal downtime and immediate improvement. Achieve a more defined and balanced chin profile non-invasively at Meva Clinic.`, image: '/images/Non-Surgical Chin Reshaping (Fillers).png', imageHint: 'chin fillers procedure' },
];

const breastServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'zmadh-gjoksit', name: 'Breast Augmentation', categorySlug: 'breasts', description: `Breast augmentation, or augmentation mammoplasty, is a sophisticated surgical procedure performed at Meva Clinic to increase breast size and enhance their shape, fullness, and symmetry. This is achieved using biocompatible saline or silicone implants, or through autologous fat transfer (fat grafting). The procedure can improve breast proportion relative to your body frame, correct congenital or acquired asymmetry, or restore breast volume lost after pregnancy, breastfeeding, or significant weight loss. Our board-certified plastic surgeons work closely with you, utilizing advanced 3D imaging and personalized consultation, to select the appropriate implant type, size, profile, and placement technique (submuscular or subglandular) for beautiful, natural-looking results that align with your unique anatomy and aesthetic aspirations. Explore your breast augmentation options and achieve the silhouette you desire at Meva Clinic.`, image: '/images/Breast Augmentation.png', imageHint: 'breast augmentation results' },
  { id: 'lift-gjoksit', name: 'Breast Lift', categorySlug: 'breasts', description: `A breast lift, medically termed mastopexy, is a surgical procedure offered at Meva Clinic designed to raise and firm sagging breasts (ptosis). This is achieved by expertly removing excess skin and strategically reshaping the underlying breast tissue and nipple-areola complex to a higher, more youthful, and aesthetically pleasing position on the chest wall. A breast lift is ideal for women experiencing breast drooping due to factors such as aging, gravity, pregnancy, breastfeeding, or significant weight fluctuations. This procedure can restore a perkier, more youthful breast contour and improve symmetry. It can also be combined with breast augmentation for enhanced volume and upper pole fullness. Discover how a breast lift performed by our skilled surgeons can rejuvenate your profile at Meva Clinic.`, image: '/images/Breast Lift.png', imageHint: 'breast lift surgery' },
  { id: 'zvog-gjoksit', name: 'Breast Reduction', categorySlug: 'breasts', description: `Breast reduction surgery, or reduction mammoplasty, at Meva Clinic is a transformative procedure designed to alleviate the significant physical and emotional discomfort associated with overly large breasts (macromastia). The surgery involves the meticulous removal of excess breast tissue, fat, and skin, resulting in smaller, lighter, and more lifted breasts that are in better proportion to your body. Key benefits include relief from chronic back, neck, and shoulder pain, improved posture, elimination of skin irritation beneath the breasts, enhanced ability to participate in physical activities, and a significant boost in self-confidence and comfort in clothing. Learn about the life-changing benefits of breast reduction surgery from our experienced surgical team at Meva Clinic.`, image: '/images/Breast Reduction.png', imageHint: 'breast reduction procedure' },
  { id: 'rikonst-gjoksit', name: 'Breast Reconstruction', categorySlug: 'breasts', description: `Breast reconstruction surgery, available at Meva Clinic, is a specialized field of plastic surgery focused on recreating the shape, appearance, size, and symmetry of a breast, most commonly performed after mastectomy or lumpectomy for breast cancer treatment. It can also address congenital breast deformities or trauma. Our compassionate and highly skilled surgical team offers a range of advanced reconstructive techniques, including implant-based reconstruction (using saline or silicone implants, often with tissue expanders) and autologous tissue flap reconstruction (utilizing your own body tissue from areas like the abdomen, back, or thighs). We provide personalized reconstruction plans, considering your medical history, body type, and personal preferences, to help restore a sense of wholeness, femininity, and confidence. Discuss your comprehensive breast reconstruction journey with our dedicated experts at Meva Clinic.`, image: '/images/Breast Reconstruction.png', imageHint: 'breast reconstruction process' },
];

const bodyServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'lift-kraheve', name: 'Arm Lift', categorySlug: 'body', description: `An arm lift, or brachioplasty, is a specialized surgical procedure performed at Meva Clinic to address significant sagging skin and excess fat deposits in the upper arms, often colloquially referred to as "bat wings." This condition can result from substantial weight loss, aging, or genetic factors. The surgery involves an incision, typically along the inner aspect of the upper arm, through which excess skin and fat are removed, and the remaining skin is redraped and tightened. This results in a firmer, more toned, and contoured arm appearance, enhancing arm definition and allowing patients to feel more confident in sleeveless attire. Achieve sleeker, more youthful arm contours with a brachioplasty tailored by our expert surgeons at Meva Clinic.`, image: '/images/Arm Lift.png', imageHint: 'arm lift results' },
  { id: 'rim-barkut', name: 'Tummy Tuck', categorySlug: 'body', description: `A tummy tuck, medically known as abdominoplasty, is a comprehensive surgical procedure offered at Meva Clinic to create a smoother, firmer, and more contoured abdominal profile. It effectively removes excess, loose skin and stubborn fat from the abdomen and, crucially, tightens weakened or separated abdominal muscles (diastasis recti) often resulting from pregnancy or significant weight fluctuations. This procedure is particularly beneficial for individuals who, despite diet and exercise, struggle with a protruding abdomen or lax skin. Our surgeons tailor the procedure (full, mini, or extended tummy tuck) to your specific anatomical needs and aesthetic goals. Explore the transformative results of abdominoplasty at Meva Clinic.`, image: '/images/Tummy Tuck.png', imageHint: 'tummy tuck surgery' },
  { id: 'liposculptura', name: 'Liposculpture', categorySlug: 'body', description: `Liposculpture at Meva Clinic represents an advanced and artistic refinement of traditional liposuction. This body contouring procedure focuses not only on the removal of unwanted, localized fat deposits but also on strategically sculpting and shaping specific body areas to enhance definition, proportion, and muscularity. It can be skillfully applied to refine areas such as the abdomen (abdominal etching), flanks ("love handles"), thighs, upper arms, back, and neck. Our experienced surgeons utilize precise, state-of-the-art techniques, such as power-assisted or ultrasound-assisted liposuction, to achieve a more athletic, toned, and aesthetically pleasing silhouette tailored to your body type. Refine your body shape with artistic liposculpture performed by our specialists at Meva Clinic.`, image: '/images/Liposculpture.png', imageHint: 'liposculpture body contouring' },
  { id: 'rim-vitheve-bbl', name: 'BBL Buttock Remodeling', categorySlug: 'body', description: `Buttock remodeling, most notably achieved through a Brazilian Butt Lift (BBL), is a highly specialized cosmetic surgery procedure at Meva Clinic that enhances the size, shape, lift, and projection of the buttocks using your body\'s own natural fat. The procedure involves two key steps: first, gentle liposuction is performed to harvest excess fat from donor areas such as the abdomen, back, flanks, or thighs. This harvested fat is then carefully processed and purified. Finally, the prepared fat is strategically injected in multiple layers into specific areas of the buttocks to create a fuller, rounder, more lifted, and aesthetically pleasing contour. This dual-benefit procedure offers natural-looking and feeling results. Discover personalized BBL procedures for your desired buttock contour with our expert surgeons at Meva Clinic.`, image: '/images/BBL Buttock Remodeling.png', imageHint: 'buttock remodel surgery' },
  { id: 'labioplastika', name: 'Labiaplasty', categorySlug: 'body', description: `Labiaplasty is a delicate surgical procedure offered at Meva Clinic to alter the size or shape of the labia minora (inner lips) and/or labia majora (outer lips) of the vulva. Women may seek this procedure for various reasons, including alleviating physical discomfort from enlarged labia during activities like exercise or intercourse, improving hygiene, enhancing aesthetic appearance, achieving symmetry, or boosting self-confidence. Our board-certified surgeons provide compassionate, confidential, and discreet care, employing precise surgical techniques to tailor the procedure to your specific anatomical needs and desired functional and aesthetic outcomes. Discuss your concerns and labiaplasty options with our sensitive and experienced professionals at Meva Clinic.`, image: '/images/Labiaplasty.png', imageHint: 'labiaplasty procedure' },
  { id: 'lift-kofsheve', name: 'Thigh Lift', categorySlug: 'body', description: `A thigh lift, or thighplasty, is a surgical procedure performed at Meva Clinic to remove excess, sagging skin and, in some cases, stubborn fat from the inner and/or outer thighs. This body contouring surgery results in smoother, firmer, and more proportionate leg contours. It is particularly beneficial for individuals who have experienced significant weight loss, or those with loose, inelastic thigh skin due to aging or genetic factors. A thigh lift can improve comfort, reduce chafing, enhance confidence, and improve the fit of clothing. Achieve more toned and aesthetically pleasing thighs with a personalized lift procedure expertly performed at Meva Clinic.`, image: '/images/Thigh Lift.png', imageHint: 'thigh lift results' },
  { id: 'gynecomastia', name: 'Gynecomastia', categorySlug: 'body', description: `Gynecomastia surgery, offered at Meva Clinic, is a specialized procedure to correct enlarged male breast tissue, creating a flatter, firmer, and more conventionally masculine chest contour. This condition can be caused by hormonal imbalances, genetics, obesity, or certain medications. The surgical approach is tailored to the individual and may involve liposuction to remove excess fatty tissue, surgical excision (glandular tissue removal) via discreet incisions, or a combination of both techniques. Gynecomastia surgery is an effective solution for men who are self-conscious about the appearance of their chest and can significantly improve self-esteem. Address gynecomastia and restore your confidence with our expert surgical team at Meva Clinic.`, image: '/images/Gynecomastia.png', imageHint: 'male chest surgery' },
  { id: 'cellulite-treatment', name: 'Cellulite Treatment', categorySlug: 'body', description: `Cellulite, characterized by its dimpled or "orange-peel" skin texture, commonly appears on the thighs, buttocks, and abdomen. At Meva Clinic, our cellulite treatments are designed to effectively reduce its appearance and improve overall skin smoothness and firmness. We offer a range of advanced options, which may include minimally invasive procedures like subcision (to release fibrous bands), energy-based devices (such as radiofrequency, acoustic wave therapy, or laser treatments that stimulate collagen and improve skin structure), or specialized injectable treatments that target the underlying structural causes of cellulite. A comprehensive consultation will determine the most effective, personalized approach for your specific type and severity of cellulite. Explore innovative cellulite reduction strategies at Meva Clinic.`, image: '/images/Cellulite Treatment.png', imageHint: 'cellulite reduction therapy' },
  { id: 'plasma-arc-body', name: 'Plasma Arc (Body)', categorySlug: 'body', description: `Plasma Arc technology, also known as fibroblast therapy or plasma pen treatment, available at Meva Clinic, can be effectively utilized for non-surgical skin tightening and rejuvenation on various body areas. This innovative treatment is particularly effective for addressing localized skin laxity, fine lines, the appearance of stretch marks (striae), and certain types of scars on the body. The plasma device creates a series of controlled, superficial micro-injuries on the skin, which triggers an immediate contraction of skin tissue and powerfully stimulates the body\'s natural collagen and elastin production over time. This leads to progressively firmer, smoother, and more rejuvenated skin. Learn about the versatility and benefits of Plasma Arc for specific body skin concerns at Meva Clinic.`, image: '/images/Plasma Arc (Body).png', imageHint: 'skin tightening body treatment' },
  { id: 'carboxytherapy', name: 'Carboxytherapy', categorySlug: 'body', description: `Carboxytherapy is a minimally invasive medical treatment offered at Meva Clinic, involving the therapeutic administration of small quantities of medical-grade carbon dioxide (CO2) gas into the subcutaneous (under the skin) or intradermal tissue. This process works by improving local blood circulation and microcirculation, enhancing oxygen delivery to tissues, stimulating neo-collagenesis (new collagen production), and improving skin elasticity. Carboxytherapy can be effective in reducing the appearance of cellulite, stretch marks, dark under-eye circles, and localized fat deposits, as well as improving overall skin tone and texture. It is a safe procedure with minimal downtime, typically performed in a series of sessions. Discover the regenerative benefits of carboxytherapy for various skin and body concerns at Meva Clinic.`, image: '/images/Carboxytherapy.png', imageHint: 'skin treatment co2' },
  { id: 'sclerotherapy', name: 'Sclerotherapy', categorySlug: 'body', description: `Sclerotherapy, performed by specialists at Meva Clinic, is a highly effective and well-established medical procedure used to treat varicose veins and smaller spider veins (telangiectasias). The treatment involves the precise injection of a specialized sclerosing solution directly into the targeted veins. This solution irritates the inner lining of the vein, causing it to swell, collapse, stick together, and eventually scar. Over time, the treated vein is naturally absorbed by the body and fades from view. Multiple sessions may be necessary to achieve optimal results and address all affected veins. Find relief from unsightly and sometimes uncomfortable veins with expert sclerotherapy at Meva Clinic.`, image: '/images/Sclerotherapy.png', imageHint: 'vein treatment legs' },
  { id: 'lipolysis', name: 'Lipolysis', categorySlug: 'body', description: `Lipolysis at Meva Clinic refers to a range of advanced, non-surgical fat reduction treatments specifically designed to break down and eliminate localized, stubborn fat cells that are often resistant to diet and exercise. These innovative techniques can include injectable lipolysis (utilizing substances like deoxycholic acid-based solutions, e.g., Kybella®, to dissolve fat cells) or energy-based devices such as cryolipolysis (fat freezing), laser lipolysis (using laser energy to liquefy fat), or radiofrequency lipolysis (using RF heat to destroy fat cells). These treatments offer a less invasive alternative to surgical liposuction for targeted body contouring and fat reduction in areas like the abdomen, flanks, thighs, chin, and arms. Target specific fat pockets and achieve a more sculpted physique with advanced lipolysis options at Meva Clinic.`, image: '/images/Lipolysis.png', imageHint: 'fat reduction procedure' },
  { id: 'laser-hair-removal', name: 'Laser Hair Removal', categorySlug: 'body', description: `Laser hair removal at Meva Clinic offers a safe, effective, and long-term solution for reducing unwanted hair on various parts of the face and body. The procedure utilizes concentrated light energy (laser) which is absorbed by the pigment (melanin) in the hair follicles. This energy converts to heat, damaging the follicles and inhibiting or delaying future hair growth. Multiple sessions are typically required for optimal, lasting results due to the cyclical nature of hair growth. Our advanced laser systems are effective for most skin types and hair colors, providing smoother, hair-free skin and liberating you from the inconvenience of constant shaving, waxing, or tweezing. Achieve lasting smoothness with state-of-the-art laser hair removal at Meva Clinic.`, image: '/images/Laser Hair Removal.png', imageHint: 'hair removal laser' },
];

const aestheticDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'teeth-whitening', name: 'Teeth Whitening', categorySlug: 'aesthetic-dentistry', description: `Professional teeth whitening treatments at Meva Clinic are expertly designed to safely and effectively lighten the natural color of your teeth, removing stubborn intrinsic and extrinsic stains and discoloration. These may be caused by factors such as food, beverages (coffee, tea, red wine), smoking, aging, or certain medications. We offer advanced, clinically proven in-office whitening systems for rapid, dramatic results, as well as custom-fitted take-home whitening kits for convenient, gradual brightening. Our dental professionals ensure a comfortable experience, delivering noticeable results for a brighter, more vibrant, and confident smile. Achieve a dazzling smile with our expert teeth whitening services at Meva Clinic.`, image: '/images/Teeth Whitening.png', imageHint: 'teeth whitening smile close up' },
  { id: 'composite-veneers', name: 'Composite Veneers', categorySlug: 'aesthetic-dentistry', description: `Composite veneers, also known as direct bonding veneers, are skillfully applied at Meva Clinic. These are thin, custom-sculpted layers of tooth-colored composite resin that are bonded directly to the front surface of teeth to enhance their appearance. This versatile cosmetic dental procedure can effectively correct a variety of imperfections, including chips, cracks, gaps between teeth (diastemas), discoloration, minor misalignment, or uneven tooth shape and size. The minimally invasive procedure is typically completed in a single dental visit and offers a conservative, cost-effective way to achieve a beautiful, natural-looking smile makeover. Transform your smile with expertly crafted composite veneers at Meva Clinic.`, image: '/images/Composite Veneers.png', imageHint: 'dental veneers beautiful smile' },
  { id: 'emax-veneers', name: 'E-Max Veneers', categorySlug: 'aesthetic-dentistry', description: `E-Max veneers, offered at Meva Clinic, represent a premium choice in cosmetic dentistry. These are ultra-thin, yet exceptionally strong, custom-fabricated shells made from high-quality lithium disilicate ceramic. E-Max veneers are renowned for their outstanding aesthetics, lifelike translucency that mimics natural tooth enamel, and superior durability. They are meticulously designed and bonded to the front surface of teeth to dramatically improve color, shape, size, length, and alignment, correcting issues like severe staining, chips, gaps, and misshapen teeth. E-Max veneers provide a long-lasting, highly stain-resistant solution for achieving a stunning, flawless smile transformation. Discover the superior beauty and quality of E-Max veneers for your ultimate smile at Meva Clinic.`, image: '/images/E-Max Veneers.png', imageHint: 'porcelain veneers smile design' },
];

const prostheticsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'dental-crowns', name: 'Dental Crowns', categorySlug: 'prosthetics', description: `Dental crowns, often referred to as "caps," are custom-made, tooth-shaped restorations meticulously fabricated at Meva Clinic to completely encase a damaged, weakened, severely decayed, or discolored tooth. A crown restores the tooth\'s original strength, shape, size, and improves its overall appearance and function. Crowns are indicated to protect a tooth after root canal treatment, support a dental bridge, cover a dental implant, or restore a fractured tooth. They can be crafted from various durable and aesthetic materials, including porcelain, ceramic, zirconia, or metal alloys, chosen to match your natural teeth. Receive durable, precisely fitted, and aesthetically pleasing dental crowns at Meva Clinic.`, image: '/images/Dental Crowns.png', imageHint: 'dental crown tooth model' },
  { id: 'dental-bridges', name: 'Dental Bridges', categorySlug: 'prosthetics', description: `Dental bridges are fixed (non-removable) prosthetic restorations expertly designed at Meva Clinic to replace one or more missing teeth, effectively "bridging" the gap. A traditional bridge consists of an artificial tooth (pontic) that is fused between two or more crowns (abutments). These abutment crowns are placed on the natural teeth or dental implants adjacent to the empty space. Bridges are crucial for restoring chewing function, maintaining facial structure by preventing bone loss, preventing remaining teeth from shifting out of position, and improving smile aesthetics and speech. Restore your complete smile and full oral function with custom-fabricated dental bridges at Meva Clinic.`, image: '/images/Dental Bridges.png', imageHint: 'dental bridge teeth model' },
  { id: 'dentures', name: 'Dentures', categorySlug: 'prosthetics', description: `Dentures are custom-made, removable prosthetic devices designed at Meva Clinic to replace missing teeth and surrounding soft tissues, restoring oral function and aesthetics. We offer expertly crafted full dentures, which replace all teeth in an upper or lower arch, and partial dentures, which replace some missing teeth while utilizing remaining natural teeth or implants for support and retention. Modern dentures are designed for a comfortable, secure fit and a natural appearance, significantly improving your ability to eat, speak, and smile with confidence. We also offer implant-supported dentures for enhanced stability. Discuss comfortable and natural-looking denture solutions with our experienced dental team at Meva Clinic.`, image: '/images/Dentures.png', imageHint: 'dentures smile model' },
];

const orthodonticsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'invisalign', name: 'Invisalign', categorySlug: 'orthodontics', description: `Invisalign®, offered at Meva Clinic, is a revolutionary orthodontic treatment system that straightens teeth discreetly and comfortably using a series of custom-made, clear, and removable aligners. These virtually invisible aligners are fabricated based on precise 3D digital scans of your teeth and are designed to gradually and gently shift your teeth into their desired position. Invisalign offers a highly aesthetic alternative to traditional metal braces, allowing you to maintain your natural smile throughout treatment. The aligners are removable for eating, drinking, brushing, and flossing, promoting better oral hygiene and convenience. Suitable for correcting a wide range of malocclusions in both teens and adults. Discover the clear path to a beautifully aligned smile with Invisalign at Meva Clinic.`, image: '/images/Invisalign.png', imageHint: 'invisalign aligners smile transparent' },
  { id: 'fixed-braces', name: 'Fixed Braces', categorySlug: 'orthodontics', description: `Fixed braces, a cornerstone of orthodontic treatment at Meva Clinic, are a traditional and highly effective method for correcting misaligned teeth, improper bites (such as overbites, underbites, crossbites), and complex jaw discrepancies. This system typically consists of metal or ceramic brackets that are bonded to each tooth and interconnected by precisely shaped archwires. These components work together to apply gentle, continuous pressure, guiding the teeth into their optimal alignment over time. Fixed braces are suitable for treating a wide range of orthodontic issues in children, adolescents, and adults, achieving predictable, stable, and lasting results for a healthy, functional, and aesthetic smile. Explore your options for optimal teeth alignment with expertly managed fixed braces at Meva Clinic.`, image: '/images/Fixed Braces.png', imageHint: 'dental braces smile metal' },
  { id: 'removable-appliances', name: 'Removable Appliances', categorySlug: 'orthodontics', description: `Removable orthodontic appliances, custom-designed at Meva Clinic, are devices that can be inserted and removed from the mouth by the patient. They serve a variety of critical functions within an orthodontic treatment plan. These appliances may be used for guiding jaw growth in growing children (functional appliances), correcting minor tooth movements or habits, expanding the dental arch to create space, or, most commonly, for maintaining the results achieved after active orthodontic treatment with fixed braces or aligners (retainers, such as Hawley or Essix retainers). Their effectiveness is highly dependent on consistent wear as prescribed by the orthodontist. Learn about the specific role and benefits of removable appliances in your comprehensive orthodontic care plan at Meva Clinic.`, image: '/images/Removable Appliances.png', imageHint: 'orthodontic appliance retainer' },
];

const restorativeDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'teeth-cleaning', name: 'Teeth Cleaning (Calculus Removal)', categorySlug: 'restorative-dentistry', description: `Professional teeth cleaning, also known as dental prophylaxis or calculus (tartar) removal, performed at Meva Clinic, is a fundamental component of maintaining optimal oral health and preventing dental diseases. Our skilled dental hygienists gently and thoroughly remove hardened plaque (calculus) and soft bacterial plaque from all tooth surfaces, including areas above and below the gumline that are often inaccessible with regular brushing and flossing. This essential procedure helps prevent tooth decay (cavities), gum disease (gingivitis and periodontitis), and halitosis (bad breath), leaving your teeth feeling exceptionally smooth, polished, and refreshed. Maintain a healthy, vibrant smile with regular professional cleanings at Meva Clinic.`, image: '/images/Teeth Cleaning (Calculus Removal).png', imageHint: 'dental cleaning hygiene tools' },
  { id: 'dental-fillings', name: 'Dental Fillings', categorySlug: 'restorative-dentistry', description: `Dental fillings are a common restorative procedure at Meva Clinic used to repair teeth damaged by decay (cavities), minor cracks, or fractures, thereby restoring their normal function, integrity, and shape. The process involves the careful removal of the decayed or damaged portion of the tooth, followed by thorough cleaning and disinfection of the prepared area. The cavity is then filled with a durable restorative material. We offer various filling materials, including tooth-colored composite resin for a natural, aesthetic appearance, amalgam (silver fillings known for durability), and ceramic restorations. Early detection and treatment of cavities with dental fillings can prevent further tooth damage and the need for more complex and costly procedures. Preserve your dental health with durable and aesthetic dental fillings at Meva Clinic.`, image: '/images/Dental Fillings.png', imageHint: 'tooth filling dental procedure' },
  { id: 'root-canal-treatment', name: 'Root Canal Treatment', categorySlug: 'restorative-dentistry', description: `Root canal treatment, also known as endodontic therapy, is a highly specialized dental procedure performed at Meva Clinic to treat infection or inflammation within the soft pulp tissue located at the center of a tooth (the root canal system). This condition can arise from deep tooth decay, repeated dental procedures on the tooth, a crack or chip in the tooth, or trauma. During the treatment, the infected or inflamed pulp is carefully removed, the inside of the tooth (root canals) is meticulously cleaned, disinfected, shaped, and then filled and sealed with a biocompatible material. Root canal treatment is crucial for saving the natural tooth, relieving severe dental pain, and preventing the spread of infection to surrounding tissues. Understand the tooth-saving benefits of expert root canal therapy at Meva Clinic.`, image: '/images/Root Canal Treatment.png', imageHint: 'root canal procedure tooth' },
];

const oralSurgeryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'tooth-extraction', name: 'Tooth Extraction', categorySlug: 'oral-surgery', description: `Tooth extraction at Meva Clinic involves the surgical removal of a tooth from its socket within the jawbone. This procedure may become necessary for various reasons, including severe, irreparable tooth decay; advanced periodontal (gum) disease leading to tooth mobility; acute or chronic infection (abscess); significant tooth damage or fracture due to trauma; impacted wisdom teeth causing pain or complications; or to create space for orthodontic treatment. Our skilled dental surgeons perform both simple (for fully erupted teeth) and surgical extractions (for impacted or broken teeth) with a strong emphasis on patient comfort, utilizing appropriate anesthesia and minimally invasive techniques to ensure optimal healing and a positive experience. Experience gentle and professional tooth extractions when indicated at Meva Clinic.`, image: '/images/Tooth Extraction.png', imageHint: 'tooth extraction dental tools' },
  { id: 'dental-implants', name: 'Dental Implants', categorySlug: 'oral-surgery', description: `Dental implants, provided by the specialists at Meva Clinic, represent the most advanced and biocompatible solution for replacing missing teeth. These are small, medical-grade titanium posts that are surgically inserted into the jawbone, where they function as artificial tooth roots. Over time, the implant fuses with the bone (a process called osseointegration), providing a strong, stable, and durable foundation for fixed or removable replacement teeth, such as crowns, bridges, or implant-supported dentures. Dental implants not only restore the look, feel, and function of natural teeth but also help preserve jawbone structure, prevent adjacent teeth from shifting, and offer a long-term, reliable solution for tooth loss. Discover the life-changing benefits of permanent tooth replacement with state-of-the-art dental implants at Meva Clinic.`, image: '/images/Dental Implants.png', imageHint: 'dental implant surgery model' },
  { id: 'apical-resection', name: 'Apical Resection (Apicoectomy)', categorySlug: 'oral-surgery', description: `An apical resection, also known as an apicoectomy or root-end surgery, is a specialized endodontic surgical procedure performed at Meva Clinic. It is typically indicated when a conventional root canal treatment has failed to resolve a persistent infection or inflammation at the tip of a tooth\'s root (the apex) and surrounding bone. The procedure involves making a small incision in the gum tissue to expose the underlying bone and the root tip. The infected tissue around the apex is removed, along with the very end of the root. A small filling (retrograde filling) is then placed to seal the end of the root canal. This microsurgical technique can effectively save a tooth that might otherwise require extraction, resolving infection and preserving natural dentition. Learn about this advanced tooth-saving surgery from our endodontic specialists at Meva Clinic.`, image: '/images/Apical Resection (Apicoectomy).png', imageHint: 'dental surgery procedure detail' },
];

const pediatricDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'primary-teeth-care', name: 'Primary Teeth Care (Milk Teeth)', categorySlug: 'pediatric-dentistry', description: `Primary teeth, commonly known as milk teeth, play a fundamentally crucial role in a child\'s overall development, including proper chewing and nutrition, speech development, and guiding the correct eruption and alignment of permanent teeth. At Meva Clinic, our pediatric dental care is centered on comprehensive prevention, early detection and intervention of dental issues, and age-appropriate education for both children and parents on optimal oral hygiene practices and diet. Our services include regular dental check-ups, professional cleanings, topical fluoride treatments, dental sealants, and guidance on habits, all delivered in a welcoming, gentle, and child-friendly environment designed to foster positive dental attitudes. Ensure a healthy foundation for your child\'s lifelong oral health at Meva Clinic.`, image: '/images/Primary Teeth Care (Milk Teeth).png', imageHint: 'child dentist kids care' },
  { id: 'teeth-fluoridation', name: 'Teeth Fluoridation', categorySlug: 'pediatric-dentistry', description: `Teeth fluoridation, provided at Meva Clinic, is a safe, highly effective, and evidence-based preventive dental treatment that involves the professional application of fluoride to children\'s teeth. Fluoride is a natural mineral that significantly strengthens tooth enamel, making it more resistant to demineralization (acid attacks) from plaque bacteria and dietary sugars. This, in turn, helps to effectively prevent tooth decay (cavities) and can even reverse early stages of enamel erosion. This painless treatment is particularly beneficial for children as their newly erupted permanent teeth and developing primary teeth are more susceptible to cavities. Protect your child\'s precious smile with regular, professionally applied fluoride treatments as an integral part of their comprehensive dental care at Meva Clinic.`, image: '/images/Teeth Fluoridation.png', imageHint: 'fluoride treatment child dental' },
  { id: 'dental-sealants', name: 'Dental Sealants', categorySlug: 'pediatric-dentistry', description: `Dental sealants, offered at Meva Clinic, are thin, protective, tooth-colored or clear plastic coatings that are professionally applied to the chewing surfaces (occlusal surfaces with pits and fissures) of children\'s back teeth (molars and premolars). These are the areas where tooth decay most frequently occurs due to their complex anatomy, which can easily trap food particles and bacteria. Sealants act as a physical barrier, effectively "sealing out" food debris and harmful bacteria, thus preventing cavities from forming in these vulnerable grooves. The application process is quick, simple, and painless, and sealants can provide robust protection for many years with proper care. Safeguard your child\'s molars effectively against decay with dental sealants at Meva Clinic.`, image: '/images/Dental Sealants.png', imageHint: 'dental sealants kids teeth' },
];


